UPDATE risk_outbox_events
SET published_at = CURRENT_TIMESTAMP, claimed_until = NULL, claim_token = NULL
WHERE id = #{id, jdbcType=OTHER} AND claim_token = #{claimToken, jdbcType=OTHER}

UPDATE risk_outbox_events
SET claimed_until = #{claimedUntil}
WHERE id = #{id, jdbcType=OTHER}
  AND claim_token = #{claimToken, jdbcType=OTHER}
  AND published_at IS NULL
  AND dead_lettered_at IS NULL
